// Extract variables from webhook input
const inputData = $input.first().json;
const body = inputData.body || inputData;

// Get the row ID (required)
const rowId = body.ID || body.id || '';
if (!rowId) {
  return { json: { error: 'Row ID is required', rowId: '' } };
}

// Get the source URL (required)
const sourceUrl = body.URL || body.url || '';
if (!sourceUrl) {
  return { json: { error: 'URL is required', rowId: rowId } };
}

// Get optional fields
const pdfLinks = body.pdfLinks || body.PDF_Links || body.pdf_links || '';
const language = body.Language || body.language || 'German';

return {
  json: {
    rowId: rowId,
    sourceUrl: sourceUrl,
    pdfLinks: pdfLinks,
    language: language
  }
};

// Extract and clean text content from HTML
const inputData = $input.first().json;
const variables = $('Merge Row Data').first().json;

// Check for HTTP request errors
if (inputData.error) {
  return {
    json: {
      error: `Failed to fetch URL: ${inputData.error}`,
      sourceUrl: variables.sourceUrl,
      rowId: variables.rowId
    }
  };
}

const html = inputData.data || inputData.body || '';

if (!html || html.length < 100) {
  return {
    json: {
      error: 'No content retrieved from URL or content too short',
      sourceUrl: variables.sourceUrl,
      rowId: variables.rowId
    }
  };
}

// Remove script and style tags
let cleaned = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
cleaned = cleaned.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
cleaned = cleaned.replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '');
cleaned = cleaned.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
cleaned = cleaned.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');
cleaned = cleaned.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');

// Remove HTML comments
cleaned = cleaned.replace(/<!--[\s\S]*?-->/g, '');

// Remove HTML tags but keep text
cleaned = cleaned.replace(/<[^>]+>/g, ' ');

// Normalize whitespace
cleaned = cleaned.replace(/\s+/g, ' ').trim();

// Decode HTML entities
cleaned = cleaned.replace(/&nbsp;/g, ' ');
cleaned = cleaned.replace(/&amp;/g, '&');
cleaned = cleaned.replace(/&lt;/g, '<');
cleaned = cleaned.replace(/&gt;/g, '>');
cleaned = cleaned.replace(/&quot;/g, '"');
cleaned = cleaned.replace(/&#39;/g, "'");
cleaned = cleaned.replace(/&apos;/g, "'");

// Limit content length to prevent LLM issues
if (cleaned.length > 10000) {
  cleaned = cleaned.substring(0, 10000) + '...';
}

// Validate minimum content length
if (cleaned.length < 200) {
  return {
    json: {
      error: 'Extracted content too short (less than 200 characters)',
      sourceUrl: variables.sourceUrl,
      rowId: variables.rowId
    }
  };
}

return {
  json: {
    cleanedContent: cleaned,
    contentLength: cleaned.length,
    sourceUrl: variables.sourceUrl,
    language: variables.language,
    rowId: variables.rowId,
    pdfLinks: variables.pdfLinks
  }
};

// Parse PDF links and download each one
const pdfLinksStr = $input.first().json.pdfLinks || '';  
const pdfLinks = pdfLinksStr.split(',').map(link => link.trim()).filter(link => link.length > 0);

// Validate PDF links - just check they are valid URLs
const validPdfLinks = pdfLinks.filter(link => {
  try {
    new URL(link);
    return true;
  } catch {
    return false;
  }
});

if (validPdfLinks.length === 0) {
  // No valid PDF links, continue without PDFs
  return {
    json: {
      ...($input.first().json),
      pdfError: 'No valid PDF links found',
      hadPdfs: false
    }
  };
}

// Return array of items for each PDF link
return validPdfLinks.map(link => ({
  json: {
    pdfUrl: link,
    cleanedContent: $input.first().json.cleanedContent,
    sourceUrl: $input.first().json.sourceUrl,
    language: $input.first().json.language,
    rowId: $input.first().json.rowId
  }
}));

// Merge all PDF text with the webpage content
const items = $input.all();
let allPdfText = '';
let pdfCount = 0;

for (const item of items) {
  if (item.json.data) {
    allPdfText += '\n\n--- PDF Content ---\n' + item.json.data;
    pdfCount++;
  }
}

// Get original content from first item
const firstItem = items[0];
const originalContent = firstItem.json.cleanedContent || '';

return {
  json: {
    cleanedContent: originalContent + allPdfText,
    contentLength: (originalContent + allPdfText).length,
    sourceUrl: firstItem.json.sourceUrl,
    language: firstItem.json.language,
    rowId: firstItem.json.rowId,
    hadPdfs: pdfCount > 0,
    pdfCount: pdfCount
  }
};

const inputData = $input.first().json;
 const cleanContent = $('Clean Content').first().json;                                                                                                              

 if (inputData.error) {
   return { json: { error: `Failed to generate blog post: ${inputData.error}`, rowId: cleanContent.rowId } };
 }

 const response = inputData.response;
 if (!response) {
   return { json: { error: 'Empty response from LLM', rowId: cleanContent.rowId } };
 }

 try {
   let title = '', meta_description = '', content = '';
   let suggested_categories = [], suggested_tags = [];

   const jsonMatch = response.match(/\{[\s\S]*\}/);

   if (jsonMatch) {
     let parsed = null;

     // Try 1: Direct JSON parse
     try {
       parsed = JSON.parse(jsonMatch[0]);
     } catch (e) {
       // Try 2: Fix newlines
       try {
         parsed = JSON.parse(jsonMatch[0].replace(/[\n\r\t]/g, ' '));
       } catch (e2) {
         // Try 3: Fix double-escaped quotes from mistral
         try {
           const fixed = jsonMatch[0].replace(/""/g, '"').replace(/[\n\r\t]/g, ' ');
           parsed = JSON.parse(fixed);
         } catch (e3) {}
       }
     }

     if (parsed) {
       title = parsed.title || '';
       meta_description = parsed.meta_description || '';
       suggested_categories = parsed.suggested_categories || [];
       suggested_tags = parsed.suggested_tags || [];
       if (parsed.content && parsed.content.length > 100) content = parsed.content;
     }
   }

   // Fallback: extract title from JSON-like text
   if (!title) {
     const m = response.match(/"title"\s*:\s*"([^"]+)"/) ||
               response.match(/""title""\s*:\s*""([^"]+)""/) ||
               response.match(/\*\*Titel?:\*\*\s*"?([^"\n]+)"?/i);
     if (m) title = m[1].trim();
   }

    // Fallback: extract meta_description
   if (!meta_description) {
     const m = response.match(/""meta_description""\s*:\s*""([\s\S]+?)""\s*,/) ||
               response.match(/"meta_description"\s*:\s*"([^"]+)"/);
     if (m) meta_description = m[1].replace(/\n/g, ' ').trim();
   }

    // Fallback: extract content from markdown code block
   if (!content || content.length < 100) {
     const mdMatch = response.match(/```markdown\s*([\s\S]+?)```/);
     if (mdMatch && mdMatch[1].length > 100) {
       content = mdMatch[1].trim();
     }
   }

   // Fallback: extract content from double-quoted JSON (mistral format)
   if (!content || content.length < 100) {
     const m = response.match(/""content""\s*:\s*\n?\s*""([\s\S]+?)""\s*\n?\s*""suggested/);
     if (m && m[1].length > 100) {
       content = m[1].trim();
     }
   }

   // Fallback: extract content from JSON-like structure
   if (!content || content.length < 100) {
     const m = response.match(/"content"\s*:\s*"([\s\S]+?)"\s*,\s*"suggested/);
     if (m && m[1].length > 100) {
       content = m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
     }
   }

   // Last resort: use full response as content
   if (!content || content.length < 100) {
     content = response.replace(/```json[\s\S]*?```/g, '').trim();
   }

   // Fallback: extract categories/tags from text
   if (suggested_categories.length === 0) {
     const m = response.match(/"suggested_categories"\s*:\s*\[([\s\S]*?)\]/);
     if (m) {
       suggested_categories = m[1].match(/"([^"]+)"/g)?.map(s => s.replace(/"/g, '')) || [];
     }
   }

   if (suggested_tags.length === 0) {
     const m = response.match(/"suggested_tags"\s*:\s*\[([\s\S]*?)\]/);
     if (m) {
       suggested_tags = m[1].match(/"([^"]+)"/g)?.map(s => s.replace(/"/g, '')) || [];
     }
   }

   if (!title || !content || content.length < 50) {
     throw new Error('Could not extract title or content');
   }

   return {
     json: {
       title, meta_description, content, suggested_categories, suggested_tags,
       keywords: $('Extract Keywords').first().json.response,
       rowId: cleanContent.rowId, language: cleanContent.language
     }
   };
 } catch (error) {
   return { json: { error: `Failed to parse LLM response: ${error.message}`, rawResponse: response.substring(0, 500), rowId: cleanContent.rowId } };
 }

// Wait for ComfyUI image generation to complete
const inputData = $input.first().json;
const blogData = $('Parse Blog Response').first().json;

let imageUrl = '';
let imageGenerated = false;

if (!inputData.error && inputData.prompt_id) {
  const promptId = inputData.prompt_id;
  const comfyHost = 'http://host.docker.internal:8188';

  // Poll ComfyUI history until the image is ready (max 10 minutes)
  const maxWait = 600000; // 10 minutes
  const pollInterval = 10000; // 10 seconds
  let elapsed = 0;

  while (elapsed < maxWait) {
    try {
      const historyResponse = await fetch(comfyHost + '/history/' + promptId);
      const history = await historyResponse.json();

      if (history[promptId] && history[promptId].status && history[promptId].status.completed) {
        const outputs = history[promptId].outputs || {};
        for (const nodeId of Object.keys(outputs)) {
          if (outputs[nodeId].images && outputs[nodeId].images.length > 0) {
            const img = outputs[nodeId].images[0];
            imageUrl = comfyHost + '/view?filename=' + encodeURIComponent(img.filename) + '&subfolder=' + (img.subfolder || '') + '&type=' + img.type;
            imageGenerated = true;
            break;
          }
        }
        if (imageGenerated) break;

        // Completed but no images found - error case
        if (history[promptId].status.status_str === 'error') break;
      }
    } catch (e) {
      // Polling error - continue waiting
    }

    await new Promise(resolve => setTimeout(resolve, pollInterval));
    elapsed += pollInterval;
  }
}

return {
  json: {
    ...blogData,
    imageUrl: imageUrl,
    imageGenerated: imageGenerated,
    imageError: inputData.error || null
  }
};

// Check for duplicate publishing - verify status is 'Approved'
const inputData = $input.first().json;
const body = inputData.body || inputData;

const status = body.Status || body.status || '';
const rowId = body.ID || body.id || body.rowId || '';

if (status !== 'Approved' && status !== 'Ready for Review') {
  if (status === 'Published') {
    return {
      json: {
        error: 'Content already published',
        rowId: rowId,
        isDuplicate: true
      }
    };
  }
  return {
    json: {
      error: `Cannot publish content with status: ${status}`,
      rowId: rowId
    }
  };
}

// Validate generated content is present before allowing publish
const title = body.Generated_Title || '';
const content = body.Generated_Content || '';
if (!title.trim() || !content.trim()) {
  return {
    json: {
      error: 'Cannot publish: Generated_Title or Generated_Content is empty. Run content generation first.',
      rowId: rowId
    }
  };
}

return {
  json: {
    ...body,
    rowId: rowId,
    rowNumber: body.rowNumber || rowId
  }
};

// Output one item per taxonomy term to create
const wpPost = $input.first().json;
const approvalData = $('Merge Approval Data').first().json;

const categories = (approvalData.Generated_Categories || '').split(',').map(c => c.trim()).filter(c => c);
const tags = (approvalData.Generated_Tags || '').split(',').map(t => t.trim()).filter(t => t);

const postId = wpPost.id;
const postLink = wpPost.link;
const rowId = approvalData.rowId;

const items = [];
for (const catName of categories) {
  items.push({ json: { type: 'category', endpoint: 'categories', name: catName, postId, postLink, rowId } });
}
for (const tagName of tags) {
  items.push({ json: { type: 'tag', endpoint: 'tags', name: tagName, postId, postLink, rowId } });
}

if (items.length === 0) {
  // No taxonomy items - pass through with skip flag
  return [{ json: { type: 'none', skip: true, postId, postLink, rowId } }];
}

return items;

// Handle LLM timeout or error for keywords
const inputData = $input.first().json;
const cleanContent = $('Clean Content').first().json;

return {
  json: {
    error: `Ollama keyword extraction failed: ${inputData.error || 'Timeout or connection error'}`,
    rowId: cleanContent.rowId,
    sourceUrl: cleanContent.sourceUrl
  }
};

// Merge webhook data with Google Sheet row data
const webhookData = $('Set Variables').first().json;
const sheetRow = $input.first().json;

// Sheet columns: ID, URL, PDF_Links, Language, Status, etc.
// Prefer sheet values, fall back to webhook values
const sourceUrl = sheetRow.URL || sheetRow.url || webhookData.sourceUrl || '';
const pdfLinks = sheetRow.PDF_Links || sheetRow.pdf_links || sheetRow.pdfLinks || webhookData.pdfLinks || '';
const language = sheetRow.Language || sheetRow.language || webhookData.language || 'German';
const rowId = webhookData.rowId || sheetRow.ID || '';

return {
  json: {
    rowId: rowId,
    sourceUrl: sourceUrl,
    pdfLinks: pdfLinks,
    language: language
  }
};

const wpPost = $('Create WordPress Draft').first().json;
const approvalData = $('Merge Approval Data').first().json;

const postId = wpPost.id;
const postLink = wpPost.link;
const rowId = approvalData.rowId;

const catNames = (approvalData.Generated_Categories || '').split(',').map(c => c.trim()).filter(c => c);
const catCount = catNames.length;

const items = $input.all();
const categoryIds = [];
const tagIds = [];

for (let i = 0; i < items.length; i++) {
  const d = items[i].json;
  let termId = null;

  // Case 1: Successful creation - direct response with id
  if (d.id && !d.code && !d.error) {
    termId = d.id;
  }
  // Case 2: term_exists in direct response
  else if (d.code === 'term_exists' && d.data && d.data.term_id) {
    termId = d.data.term_id;
  }
  // Case 3: Error wrapper from continueOnFail - extract term_id via regex
  else if (d.error && d.error.message) {
    const msg = d.error.message;
    // Look for term_id in the error message string (handles escaped JSON)
    const termIdMatch = msg.match(/term_id["\\\s:]+(\d+)/);
    if (termIdMatch) {
      termId = parseInt(termIdMatch[1], 10);
    } else {
      // Try additional_data array
      const addMatch = msg.match(/additional_data["\\\s:\[]+(\d+)/);
      if (addMatch) {
        termId = parseInt(addMatch[1], 10);
      }
    }
  }

  if (termId) {
    if (i < catCount) categoryIds.push(termId);
    else tagIds.push(termId);
  }
}

// Build update payload - assign taxonomies only, keep as draft
const updatePayload = {};
if (categoryIds.length > 0) updatePayload.categories = categoryIds;
if (tagIds.length > 0) updatePayload.tags = tagIds;

return {
  json: {
    postId,
    postLink,
    rowId,
    categoryIds,
    tagIds,
    updateBody: JSON.stringify(updatePayload)
  }
};

// Merge Google Sheet data with webhook data for approval
const webhookData = $('Check Duplicate').first().json;
const sheetRow = $input.first().json;

const rowId = webhookData.rowId || sheetRow.ID || '';
const title = sheetRow.Generated_Title || webhookData.Generated_Title || '';
const content = sheetRow.Generated_Content || webhookData.Generated_Content || '';
const metaDescription = sheetRow.Generated_Meta_Description || webhookData.Generated_Meta_Description || '';
const categories = sheetRow.Generated_Categories || webhookData.Generated_Categories || '';
const tags = sheetRow.Generated_Tags || webhookData.Generated_Tags || '';

// Normalize Image_URL: handle legacy comfyui:// and comfyui-local:// formats
let imageUrl = sheetRow.Image_URL || webhookData.Image_URL || '';
if (imageUrl.startsWith('comfyui://') || imageUrl.startsWith('comfyui-local://')) {
  const rawName = imageUrl.replace(/^comfyui(-local)?:\/\//, '');
  // If it already has an extension, use as-is; otherwise append _00001_.png
  const filename = /\.(png|jpg|jpeg|webp)$/i.test(rawName)
    ? rawName
    : rawName + '_00001_.png';
  imageUrl = `http://host.docker.internal:8188/view?filename=${encodeURIComponent(filename)}&subfolder=&type=output`;
}

return {
  json: {
    rowId,
    Generated_Title: title,
    Generated_Content: content,
    Generated_Meta_Description: metaDescription,
    Generated_Categories: categories,
    Generated_Tags: tags,
    Image_URL: imageUrl
  }
};
